import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DncwoWA8.js";const o="/projects/ai-skills/diagrams/challenge-a-design.svg",u=JSON.parse('{"title":"Challenge a plan without implementing it","description":"","frontmatter":{"title":"Challenge a plan without implementing it"},"headers":[],"relativePath":"workflows/challenge-a-design.md","filePath":"workflows/challenge-a-design.md"}'),r={name:"workflows/challenge-a-design.md"};function l(n,e,h,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="challenge-a-plan-without-implementing-it" tabindex="-1">Challenge a plan without implementing it <a class="header-anchor" href="#challenge-a-plan-without-implementing-it" aria-label="Permalink to &quot;Challenge a plan without implementing it&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/plan-a-project.html">Plan a project or feature</a>.</p><p>A confident proposal may conceal unresolved assumptions or decisions.</p><p><strong>Finish with:</strong> Sharper decisions, unresolved risks, and evidence needed to choose the next step.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+o+'" alt="Challenge a plan without implementing it: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/challenge-a-design.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/challenge-a-design.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/challenge-a-design.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. This selection includes the catalogued instruction requirements <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a>. Resolve them before use.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Request an interview.</strong> <a href="/projects/ai-skills/skills/grill-me.html"><code>grill-me</code></a> provides the guidance for this step.</li><li><strong>Pressure-test decisions.</strong> <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> provides the guidance for this step.</li><li><strong>Check open assumptions.</strong> <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> provides the guidance for this step.</li><li><strong>Summarize open decisions.</strong> <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Stop after the interview when the decision is clear, or research a disputed fact. The optional wait-what branch asks for an unclear reply to be explained again; it is not a design critic.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/research.html"><code>research</code></a> when a decision depends on facts, alternatives, feasibility, or evidence that you do not yet have.</li><li>Choose <a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> when the direction is agreed but observable behavior, acceptance criteria, constraints, or test boundaries remain unclear.</li><li>Choose <a href="/projects/ai-skills/skills/wait-what.html"><code>wait-what</code></a> when the last answer is hard to understand or omits context needed to follow the current proposal.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
